#include <vector>
#include <algorithm>

class Solution {
public:
    long long minIncreases(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return 0;
        long long cost = 0;
        for (int i = 1; i < n - 1; i += 2) {
            int req = std::max(nums[i - 1], nums[i + 1]) + 1;
            if (nums[i] < req) cost += req - nums[i];
        }
        return cost;
    }
};

class Solution {
    public long minIncreases(int[] nums) {
        int n = nums.length;
        if (n <= 2) return 0;
        long cost = 0;
        for (int i = 1; i < n - 1; i += 2) {
            int req = Math.max(nums[i - 1], nums[i + 1]) + 1;
            if (nums[i] < req) cost += req - nums[i];
        }
        return cost;
    }
}

